import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    k = min(k, len(jobs))

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)
    sink = m - 1

    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(sink):
        add_edge(i, i + 1, k, 0)

    for s, e, pay in jobs:
        add_edge(idx[s], idx[e], 1, -pay)

    INF = 10**18
    pot = [INF] * m
    pot[0] = 0
    for u in range(m):
        pu = pot[u]
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and pu + cost < pot[v]:
                pot[v] = pu + cost

    flow = 0
    total_cost = 0

    while flow < k:
        dist = [INF] * m
        parent_node = [-1] * m
        parent_edge = [-1] * m
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            pu = pot[u]
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_node[v] = u
                        parent_edge[v] = ei
                        heapq.heappush(heap, (nd, v))

        if dist[sink] == INF:
            break

        for v in range(m):
            if dist[v] < INF:
                pot[v] += dist[v]

        if pot[sink] >= 0:
            break

        f = k - flow
        v = sink
        while v != 0:
            u = parent_node[v]
            cap = adj[u][parent_edge[v]][1]
            if cap < f:
                f = cap
            v = u

        v = sink
        while v != 0:
            u = parent_node[v]
            edge = adj[u][parent_edge[v]]
            edge[1] -= f
            adj[v][edge[3]][1] += f
            v = u

        flow += f
        total_cost += f * pot[sink]

    return -total_cost
